import{_ as a,o as t,c as o,a2 as c}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"OTA and A/B architecture","description":"","frontmatter":{},"headers":[],"relativePath":"arch/ota-ab.md","filePath":"arch/ota-ab.md"}'),s={name:"arch/ota-ab.md"};function d(r,e,i,n,h,l){return t(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="ota-and-a-b-architecture" tabindex="-1">OTA and A/B architecture <a class="header-anchor" href="#ota-and-a-b-architecture" aria-label="Permalink to &quot;OTA and A/B architecture&quot;">​</a></h1><h2 id="slots-and-flags" tabindex="-1">Slots and flags <a class="header-anchor" href="#slots-and-flags" aria-label="Permalink to &quot;Slots and flags&quot;">​</a></h2><p><code>kernel/ota/ota_ab.{c,h}</code>: two slots + a boot flag + per-slot state (successful / booting / failed). GRUB&#39;s menu scripts read the flag; <code>update</code> writes it after a staged install; <code>rollback</code> flips it back.</p><h2 id="the-update-chain" tabindex="-1">The update chain <a class="header-anchor" href="#the-update-chain" aria-label="Permalink to &quot;The update chain&quot;">​</a></h2><p><code>kernel/ota/ota_update.{c,h}</code>: check (manifest fetch + parse), download (http/https to a file), verify (SHA256 + signature), install (onto the inactive slot), set_boot (flag), rollback, and status queries. The L1 surface mirrors it 1:1 (<code>l1_ext_check_update</code>, <code>l1_ext_update_download</code>, ...).</p><h2 id="the-manifest" tabindex="-1">The manifest <a class="header-anchor" href="#the-manifest" aria-label="Permalink to &quot;The manifest&quot;">​</a></h2><p><code>update.json</code> on the release site: version, build, time, changes, package URL, package SHA256, package size. <code>checkupdate</code> reads the URL from <code>/etc/opencube.conf</code> and parses exactly this.</p><h2 id="the-package" tabindex="-1">The package <a class="header-anchor" href="#the-package" aria-label="Permalink to &quot;The package&quot;">​</a></h2><p><code>opencube-&lt;version&gt;-update.tar.gz</code>: the new kernel ELF + manifest. Deterministic within the build day (the manifest embeds the UTC date); the ELF itself is fully reproducible.</p><h2 id="in-guest-tests" tabindex="-1">In-guest tests <a class="header-anchor" href="#in-guest-tests" aria-label="Permalink to &quot;In-guest tests&quot;">​</a></h2><p><code>ab_partition_test</code>, <code>update_*_test</code> (the whole chain, packaged as commands), <code>checkupdate_test</code> (URL/JSON units + live probe), and the release-gate E2E that walks check-&gt;download-&gt;verify-&gt;install-&gt;reboot for real.</p>',11)])])}const f=a(s,[["render",d]]);export{u as __pageData,f as default};
